from z3 import *
import itertools

n = 14
min_edges = 18

# Edge variables
x = {}
for i in range(n):
    for j in range(i+1, n):
        x[(i,j)] = Bool(f"x_{i}_{j}")

# Color variables
c = [Int(f"c_{i}") for i in range(n)]

s = Solver()
s.set(timeout=30000)  # 30 seconds

# Color constraints: c[i] in {0, 1, 2}
for i in range(n):
    s.add(Or(c[i] == 0, c[i] == 1, c[i] == 2))

# Edge implies different colors
for i in range(n):
    for j in range(i+1, n):
        s.add(Implies(x[(i,j)], c[i] != c[j]))

# At least 18 edges
edge_vars = [x[(i,j)] for i in range(n) for j in range(i+1, n)]
s.add(Sum([If(e, 1, 0) for e in edge_vars]) >= min_edges)

# No triangles (cycles of length 3)
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            s.add(Not(And(x[(i,j)], x[(j,k)], x[(i,k)])))

# No 4-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                s.add(Not(And(x[(i,j)], x[(j,k)], x[(k,l)], x[(i,l)])))
                s.add(Not(And(x[(i,j)], x[(j,l)], x[(k,l)], x[(i,k)])))
                s.add(Not(And(x[(i,k)], x[(j,k)], x[(j,l)], x[(i,l)])))

print("Constraints added, solving...")
result = s.check()
print(f"Result: {result}")

if result == sat:
    m = s.model()
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            if m.evaluate(x[(i,j)]):
                edges.append((i, j))
    print(f"Found graph with {len(edges)} edges")
    print(edges)
else:
    print("UNSAT")

