from collections import deque

def find_shortest_cycle(n, adj):
    min_cycle = float('inf')
    for start in range(n):
        # BFS from start
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

girth = find_shortest_cycle(n, adj)
print(f"Girth: {girth}")

# Verify no cycles of length < 7
if girth >= 7:
    print("Girth constraint satisfied!")
else:
    print(f"FAIL: Girth is {girth}, need >= 7")

